from manim import *
from narrated import NarratedScene
from pathlib import Path
import json
import numpy as np

HERE=Path(__file__).resolve().parent
INK='#252621'; RED='#d83e3e'; OLIVE='#7f8d60'; YELLOW='#f4cc3d'; PAPER='#eee9da'; GREY='#b7b5a5'; TEAL='#398c83'

class Chapter(NarratedScene):
    def txt(self,s,size=32,color=INK,font='Hind',weight=NORMAL):
        return Text(s,font=font,font_size=size,color=color,weight=weight)
    def fit(self,m,w):
        if m.width>w:m.scale_to_fit_width(w)
        return m
    def label(self,s,pos=(0,0,0),fill=PAPER,size=28,w=None):
        t=self.txt(s,size)
        if w:self.fit(t,w-.35)
        r=Rectangle(width=t.width+.34,height=t.height+.22,stroke_color=INK,stroke_width=1.3,fill_color=fill,fill_opacity=1)
        sh=r.copy().set_fill(INK).set_stroke(width=0).shift(RIGHT*.06+DOWN*.06)
        return VGroup(sh,r,t).move_to(pos)
    def heading(self,kicker,title):
        a=self.txt(kicker,24,font='Oswald').move_to([-5.85,3.47,0],aligned_edge=LEFT)
        t=self.fit(self.txt(title,40,weight=BOLD),12).move_to([-5.85,2.78,0],aligned_edge=LEFT)
        l=Line([-5.85,2.35,0],[5.85,2.35,0],color=INK,stroke_width=1)
        return VGroup(a,t,l)
    def show(self,m,t=None,d=.5):
        if t is not None:self.wait_until(t,lead=.15)
        self.play(FadeIn(m,shift=UP*.10),run_time=d)
        return m
    def wipe(self):
        mobs=[m for m in self.mobjects if m is not self.bg]
        if mobs:self.play(*[FadeOut(m) for m in mobs],run_time=.35)
    def arr(self,a,b,color=INK):
        return Arrow(a,b,buff=.08,color=color,stroke_width=3,max_tip_length_to_length_ratio=.16)
    def map(self):
        data=json.loads((HERE/'assets/map.json').read_text())
        g=VGroup(); countries={}
        def p(x,y):return np.array([-6.05+(x-94)*.145,-2.45+(y-17)*.145,0])
        for name,polys in data.items():
            part=VGroup(*[Polygon(*[p(x,y) for x,y in poly],stroke_color='#77796e',stroke_width=.7,fill_color='#cdc8af',fill_opacity=1) for poly in polys])
            countries[name]=part;g.add(part)
        return g,countries,p
    def factory(self,pos,scale=1):
        body=Polygon([-1,-.6,0],[-1,.35,0],[-.35,.05,0],[-.35,.35,0],[.3,.05,0],[.3,.35,0],[1,.05,0],[1,-.6,0],fill_color=OLIVE,fill_opacity=1,stroke_color=INK,stroke_width=2)
        chimney=Rectangle(width=.22,height=1,fill_color=INK,fill_opacity=1,stroke_width=0).move_to([.65,.6,0])
        wins=VGroup(*[Square(.16,fill_color=PAPER,fill_opacity=1,stroke_width=0).move_to([x,-.3,0]) for x in [-.65,-.2,.25,.7]])
        return VGroup(body,chimney,wins).scale(scale).move_to(pos)
    def construct(self):
        self.bg=ImageMobject(str(HERE/'assets/paper.png')).set(width=14.23,height=8)
        self.add(self.bg)
        # Opening
        top=self.txt('आधुनिकता के रास्ते',28).move_to([0,2.6,0])
        num=self.txt('01',72,font='Oswald').move_to([-4.9,.35,0])
        bar=Rectangle(width=9.7,height=.67,fill_color=YELLOW,fill_opacity=1,stroke_width=0).move_to([.65,-.28,0])
        title=self.txt('एक चुनौती, अलग रास्ते',54,weight=BOLD).move_to([.65,.35,0])
        foot=self.txt('CHINA  /  JAPAN',28,font='Oswald').move_to([0,-1.5,0])
        self.show(VGroup(top,num),0,d=.45)
        self.show(VGroup(bar,title),1.3,d=.65);self.show(foot,2.5)
        self.wait_until(3.8);self.wipe()
        # Establish geography
        h=self.heading('01 / EAST ASIA','उन्नीसवीं सदी की शुरुआत')
        mp,c,p=self.map()
        note=self.txt('स्थान-संदर्भ • वर्तमान सीमाएँ',24).move_to([-2.1,-3.35,0])
        self.show(VGroup(h,mp,note),4.1,d=.7)
        china=self.label('CHINA',p(111,35),fill=PAPER,size=28)
        japan=self.label('JAPAN',p(142,31),fill=PAPER,size=26)
        qing=self.label('Qing राजवंश',[4.5,1.15,0],OLIVE,32)
        strength=self.txt('विशाल देश\nपुरानी परंपरा\nमजबूत दिखती सत्ता',32,line_spacing=1.1).move_to([4.5,-.3,0])
        self.wait_until(10.4);self.play(c['China'].animate.set_fill(OLIVE),FadeIn(china),run_time=.6)
        self.show(qin
